def _check_compartment(compartment):
    """Check whether the compartment is valid.

    First check if the compartment is missing, and then check if it is a
    qualified string type, finally check if the string is empty. For all checks,
    it would raise a ParseError with the corresponding message.

    Args:
        compartment: a string type object to be checked.
    """
    if compartment is None:
        raise ParseError('The compartment is missing.')
    if not isinstance(compartment, str):
        raise ParseError('The compartment should be a string.')
    if not compartment:
        raise ParseError('The compartment cannot be an empty string.')


